#include "mongoose.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static Node* newnode(NodeKind k,Token t){Node*n=calloc(1,sizeof*n);if(n){n->kind=k;n->token=t;}return n;}
static void drop(Node*n){if(!n)return;switch(n->kind){case N_UNARY:drop(n->as.unary.operand);break;case N_BINARY:drop(n->as.binary.left);drop(n->as.binary.right);break;case N_VAR:drop(n->as.var.value);break;case N_BLOCK:case N_PROGRAM:for(size_t i=0;i<n->as.list.count;i++)drop(n->as.list.items[i]);free(n->as.list.items);break;case N_IF:drop(n->as.conditional.condition);drop(n->as.conditional.then_branch);drop(n->as.conditional.else_branch);break;case N_WHILE:drop(n->as.loop.condition);drop(n->as.loop.body);break;case N_FUNCTION:free(n->as.function.params);drop(n->as.function.body);break;case N_CALL:for(size_t i=0;i<n->as.call.arg_count;i++)drop(n->as.call.args[i]);free(n->as.call.args);break;case N_INDEX:drop(n->as.index.target);drop(n->as.index.index);break;case N_RETURN:drop(n->as.ret.value);break;case N_ASSIGN:drop(n->as.assign.target);drop(n->as.assign.value);break;default:break;}free(n);}
static bool pushnode(Node***v,size_t*n,size_t*c,Node*x){if(*n==*c){size_t z=*c?*c*2:4;Node**q=realloc(*v,z*sizeof*q);if(!q)return false;*v=q;*c=z;}(*v)[(*n)++]=x;return true;}
typedef struct{const TokenArray*t;size_t p;Diagnostic*e;bool bad;}Parser;
static Token pk(Parser*p){return p->t->items[p->p<p->t->count?p->p:p->t->count-1];}
static Token pop(Parser*p){Token t=pk(p);if(t.type!=T_EOF&&p->p<p->t->count)p->p++;return t;}
static bool eat(Parser*p,TokenType t){if(pk(p).type==t){pop(p);return true;}return false;}
static bool need(Parser*p,TokenType t,const char*m){if(eat(p,t))return true;Token x=pk(p);if(!p->bad&&p->e){snprintf(p->e->message,sizeof p->e->message,"%s",m);p->e->line=x.line;p->e->column=x.column;}p->bad=true;return false;}
static Name nm(Token t){return(Name){t.start,t.length};}
static int precedence(TokenType t){switch(t){case T_ASSIGN:return 1;case T_OR:case T_AND:return 2;case T_EQ:case T_NE:return 3;case T_LT:case T_LE:case T_GT:case T_GE:return 4;case T_PLUS:case T_MINUS:return 5;case T_STAR:case T_SLASH:case T_FLOOR_DIV:case T_PERCENT:return 6;case T_POWER:return 8;case T_LPAREN:case T_LBRACKET:return 9;default:return 0;}}
static Node* expression(Parser*p,int min);
static Node* primary(Parser*p){Token t=pop(p);Node*n;switch(t.type){case T_NUMBER:n=newnode(N_NUMBER,t);if(n)n->as.number=strtod(t.start,NULL);return n;case T_TRUE:case T_FALSE:n=newnode(N_BOOL,t);if(n)n->as.boolean=t.type==T_TRUE;return n;case T_IDENT:n=newnode(N_IDENT,t);if(n)n->as.name=nm(t);return n;case T_MINUS:case T_NOT:n=newnode(N_UNARY,t);if(n){n->as.unary.op=t;n->as.unary.operand=expression(p,7);}return n;case T_LPAREN:n=expression(p,1);if(!need(p,T_RPAREN,"expected ')'")){drop(n);return NULL;}return n;default:if(p->e){snprintf(p->e->message,sizeof p->e->message,"expected expression");p->e->line=t.line;p->e->column=t.column;}p->bad=true;return NULL;}}
static Node* expression(Parser*p,int min){Node*l=primary(p);if(!l)return NULL;for(;;){Token op=pk(p);int pr=precedence(op.type);if(!pr||pr<min)break;pop(p);if(op.type==T_LPAREN){if(l->kind!=N_IDENT){drop(l);p->bad=true;return NULL;}Node*c=newnode(N_CALL,op);if(!c){drop(l);return NULL;}c->as.call.name=l->as.name;free(l);if(pk(p).type!=T_RPAREN){do{Node*a=expression(p,1);if(!a||!pushnode(&c->as.call.args,&c->as.call.arg_count,&c->as.call.arg_capacity,a)){drop(a);drop(c);p->bad=true;return NULL;}}while(eat(p,T_COMMA));}if(!need(p,T_RPAREN,"expected ')' after call arguments")){drop(c);return NULL;}l=c;continue;}if(op.type==T_LBRACKET){Node*i=expression(p,1);if(!need(p,T_RBRACKET,"expected ']'")){drop(l);drop(i);return NULL;}Node*x=newnode(N_INDEX,op);if(!x){drop(l);drop(i);return NULL;}x->as.index.target=l;x->as.index.index=i;l=x;continue;}Node*r=expression(p,(op.type==T_ASSIGN||op.type==T_POWER)?pr:pr+1);if(!r){drop(l);return NULL;}Node*x=newnode(op.type==T_ASSIGN?N_ASSIGN:N_BINARY,op);if(!x){drop(l);drop(r);return NULL;}if(x->kind==N_ASSIGN){x->as.assign.target=l;x->as.assign.value=r;}else{x->as.binary.op=op;x->as.binary.left=l;x->as.binary.right=r;}l=x;}return l;}
static Node* statements(Parser*p,TokenType stop1,TokenType stop2){Node*b=newnode(N_BLOCK,pk(p));if(!b)return NULL;while(pk(p).type!=T_EOF&&pk(p).type!=stop1&&pk(p).type!=stop2&&!p->bad){while(eat(p,T_NEWLINE)){}if(pk(p).type==T_EOF||pk(p).type==stop1||pk(p).type==stop2)break;Token t=pk(p);Node*s=NULL;
if(eat(p,T_LET)){Token id=pk(p);if(!need(p,T_IDENT,"expected variable name")||!need(p,T_ASSIGN,"expected '=' after variable name"))break;s=newnode(N_VAR,t);if(s){s->as.var.name=nm(id);s->as.var.value=expression(p,1);}}
else if(eat(p,T_BREAK)){s=newnode(N_BREAK,t);}
else if(eat(p,T_CONTINUE)){s=newnode(N_CONTINUE,t);}
else if(eat(p,T_WHILE)){Node*c=expression(p,1);if(!need(p,T_DO,"expected 'do' after while condition")){drop(c);break;}while(eat(p,T_NEWLINE)){}Node*b=statements(p,T_STOP,T_EOF);if(!need(p,T_STOP,"expected 'stop' after while loop")){drop(c);drop(b);break;}s=newnode(N_WHILE,t);if(s){s->as.loop.condition=c;s->as.loop.body=b;}else{drop(c);drop(b);}}
else if(eat(p,T_IF)){Node*c=expression(p,1);if(!need(p,T_THEN,"expected 'then'"))break;while(eat(p,T_NEWLINE)){}Node*a=statements(p,T_ELSE,T_STOP),*z=NULL;if(eat(p,T_ELSE)){while(eat(p,T_NEWLINE)){}z=statements(p,T_STOP,T_EOF);}if(!need(p,T_STOP,"expected 'stop' after if")){drop(c);drop(a);drop(z);break;}s=newnode(N_IF,t);if(s){s->as.conditional.condition=c;s->as.conditional.then_branch=a;s->as.conditional.else_branch=z;}else{drop(c);drop(a);drop(z);}}
else if(eat(p,T_FUNCTION)){Token id=pk(p);if(!need(p,T_IDENT,"expected function name")||!need(p,T_LPAREN,"expected '('"))break;s=newnode(N_FUNCTION,t);if(!s)break;s->as.function.name=nm(id);size_t cap=0;if(pk(p).type!=T_RPAREN){do{Token a=pk(p);if(!need(p,T_IDENT,"expected parameter name"))break;if(s->as.function.param_count==cap){size_t z=cap?cap*2:4;Name*q=realloc(s->as.function.params,z*sizeof*q);if(!q){p->bad=true;break;}s->as.function.params=q;cap=z;}s->as.function.params[s->as.function.param_count++]=nm(a);}while(eat(p,T_COMMA));}if(!need(p,T_RPAREN,"expected ')' after parameters")){drop(s);break;}while(eat(p,T_NEWLINE)){}s->as.function.body=statements(p,T_STOP,T_EOF);if(!need(p,T_STOP,"expected 'stop' after function")){drop(s);break;}}
else if(eat(p,T_RETURN)){s=newnode(N_RETURN,t);if(s&&pk(p).type!=T_NEWLINE&&pk(p).type!=T_EOF&&pk(p).type!=T_STOP)s->as.ret.value=expression(p,1);}
else s=expression(p,1);
if(!s){p->bad=true;break;}if(!pushnode(&b->as.list.items,&b->as.list.count,&b->as.list.capacity,s)){drop(s);p->bad=true;break;}if(pk(p).type!=T_NEWLINE&&pk(p).type!=T_EOF&&pk(p).type!=stop1&&pk(p).type!=stop2){Token x=pk(p);if(p->e){snprintf(p->e->message,sizeof p->e->message,"expected statement separator");p->e->line=x.line;p->e->column=x.column;}p->bad=true;break;}while(eat(p,T_NEWLINE)){} }
return b;}
bool parse_tokens(const TokenArray*t,Ast*out,Diagnostic*e){if(!t||!t->items||!t->count||!out)return false;memset(out,0,sizeof*out);Parser p={t,0,e,false};Node*r=statements(&p,T_EOF,T_EOF);if(!r||p.bad||pk(&p).type!=T_EOF){drop(r);if(!p.bad&&e){Token x=pk(&p);snprintf(e->message,sizeof e->message,"unexpected token after program");e->line=x.line;e->column=x.column;}return false;}r->kind=N_PROGRAM;out->root=r;return true;}
void free_ast(Ast*a){if(a){drop(a->root);a->root=NULL;}}

